mapper.select:
WITH dense_search AS ( SELECT id, content, row_number() OVER (ORDER BY embedding <=> #{queryVector}::vector) AS rank FROM knowledge_chunk ORDER BY embedding <=> #{queryVector}::vector LIMIT #{k} ),
sparse_search AS ( SELECT id, content, row_number() OVER (ORDER BY ts_rank(to_tsvector('simple', content), plainto_tsquery('simple', #{queryText})) DESC) AS rank FROM knowledge_chunk WHERE to_tsvector('simple', content) @@ plainto_tsquery('simple', #{queryText}) ORDER BY ts_rank(to_tsvector('simple', content), plainto_tsquery('simple', #{queryText})) DESC LIMIT #{k} )
SELECT COALESCE(d.id, s.id) AS id, COALESCE(d.content, s.content) AS content, (COALESCE(1.0 / (60 + d.rank), 0.0) + COALESCE(1.0 / (60 + s.rank), 0.0)) AS rrf_score FROM dense_search d FULL OUTER JOIN sparse_search s ON d.id = s.id ORDER BY rrf_score DESC LIMIT #{k}
